const ids = [];
for (const item of $input.all()) {
  if (item.json.place_id) ids.push(String(item.json.place_id));
}
return [{ json: { ids } }];

const config = $('Configuração').first().json;
const lista = String(config.termos || '')
  .split(/[,;\n]/)
  .map((t) => t.trim())
  .filter(Boolean);
const cidade = String(config.cidade || '').trim();
if (!lista.length) return [];
return lista.map((termo) => ({
  json: {
    termo,
    consulta: cidade ? termo + ' em ' + cidade : termo,
  },
}));

const config = $('Configuração').first().json;
const termos = $('Termos').all();

function telefoneE164(raw) {
  let digits = String(raw || '').replace(/\D/g, '');
  if (!digits) return '';
  if (digits.startsWith('00')) digits = digits.slice(2);
  if (digits.startsWith('0')) digits = digits.replace(/^0+/, '');
  if ((digits.length === 10 || digits.length === 11) && !digits.startsWith('55')) {
    digits = '55' + digits;
  }
  if (digits.length < 12 || digits.length > 13) return '';
  return digits;
}

const out = [];
for (const item of $input.all()) {
  const places = Array.isArray(item.json.places) ? item.json.places : [];
  let termo = '';
  const paired = item.pairedItem;
  const index = Array.isArray(paired) ? (paired[0] && paired[0].item) : (paired && paired.item);
  if (typeof index === 'number' && termos[index] && termos[index].json) {
    termo = termos[index].json.termo || '';
  }
  for (const place of places) {
    const nome = place.displayName && place.displayName.text ? String(place.displayName.text).trim() : '';
    const placeId = place.id ? String(place.id) : '';
    if (!nome || !placeId) continue;
    const site = place.websiteUri || '';
    const social = /facebook\.com|instagram\.com|tiktok\.com|linktr\.ee|wa\.me|whatsapp\.com|google\.[^/]+\/maps/i.test(site);
    const telefone = telefoneE164(place.internationalPhoneNumber) || telefoneE164(place.nationalPhoneNumber);
    out.push({
      json: {
        place_id: placeId,
        nome,
        telefone,
        telefone_exibicao: place.nationalPhoneNumber || place.internationalPhoneNumber || '',
        email: '',
        site,
        buscar_email: site.startsWith('http') && !social ? 'sim' : 'nao',
        endereco: place.formattedAddress || '',
        maps: place.googleMapsUri || '',
        avaliacao: place.rating == null ? '' : String(place.rating),
        termo,
        cidade: config.cidade || '',
      },
    });
  }
}
return out;

const conhecidos = new Set((($('Juntar IDs').first().json.ids) || []).map((id) => String(id)));
const vistos = new Set();
const out = [];
for (const item of $input.all()) {
  const id = String(item.json.place_id || '');
  if (!id || conhecidos.has(id) || vistos.has(id)) continue;
  vistos.add(id);
  out.push(item);
}
return out;

