const config = $('Configuração').first().json;
const canal = String(config.canal || 'email').toLowerCase();
const limite = Number(config.limite_envios) || 15;

function limpo(v) {
  const s = String(v || '').replace(/[\r\n\t]+/g, ' ').replace(/\s{2,}/g, ' ').trim();
  return (s || '-').slice(0, 200);
}

const bruto = [];
const vistos = new Set();
for (const item of $input.all()) {
  const lead = item.json || {};
  const placeId = String(lead.place_id || '').trim();
  if (!placeId || vistos.has(placeId)) continue;
  if (String(lead.status || '').trim().toLowerCase() !== 'enviar') continue;
  vistos.add(placeId);
  const email = String(lead.email || '').trim();
  const telefone = String(lead.telefone || '').replace(/\D/g, '');
  const podeEmail = Boolean(email) && canal !== 'whatsapp_api';
  const podeWa = Boolean(telefone) && (canal === 'whatsapp_api' || canal === 'ambos');
  let acao = 'sem_contato';
  const texto = String(lead.mensagem || '') + ' ' + String(lead.assunto || '');
  if (texto.includes('COLOQUE_')) acao = 'rascunho_incompleto';
  else if (podeEmail && podeWa) acao = 'ambos';
  else if (podeEmail) acao = 'email';
  else if (podeWa) acao = 'whatsapp';
  else if (telefone) acao = 'so_link';
  const body = {
    messaging_product: 'whatsapp',
    to: telefone,
    type: 'template',
    template: {
      name: String(config.whatsapp_template || 'primeiro_contato').trim() || 'primeiro_contato',
      language: { code: 'pt_BR' },
      components: [
        {
          type: 'body',
          parameters: [
            { type: 'text', text: limpo(config.nome_remetente) },
            { type: 'text', text: limpo(config.nome_banda) },
            { type: 'text', text: limpo(lead.nome) },
          ],
        },
      ],
    },
  };
  bruto.push({
    json: {
      place_id: placeId,
      nome: lead.nome || '',
      email,
      telefone,
      assunto: lead.assunto || '',
      mensagem: lead.mensagem || '',
      acao,
      whatsappBody: JSON.stringify(body),
    },
  });
}

const enviar = bruto.filter((item) => ['email', 'whatsapp', 'ambos'].includes(item.json.acao)).slice(0, limite);
const ajustar = bruto.filter((item) => !['email', 'whatsapp', 'ambos'].includes(item.json.acao));
return enviar.concat(ajustar);

